  const edges = straightEdges(cmds).filter((e) => e.len > 0.2);
  const hs = edges.filter((e) => Math.abs(e.dy) < 1e-6).map((e) => e.a[1]);
  const vs = edges.filter((e) => Math.abs(e.dx) < 1e-6).map((e) => e.a[0]);
