// ───────────────────────────────────────────────────────────────────────────
// PART I — selftest. A mock Figma tree exercises the SERIALISED extractor (the
// text `script` emits, not the function itself), then the normaliser and the
// geometry helpers. All geometry in here is generated by this file: no third-
// party drawing is copied into a tracked file (research/references/ is the only
// place licensed geometry may live).
// ───────────────────────────────────────────────────────────────────────────
const KAPPA = 0.5522847498;   // cubic handle for a quarter circle, in units of the radius
// Path of a rectangle w×h whose corners are rounded to r (r = 0: sharp), in Figma's grammar.
function roundedRectPath(w, h, r) {
  if (!r) return `M 0 0 L 0 ${h} L ${w} ${h} L ${w} 0 L 0 0 Z`;
  const k = r * KAPPA;
  return `M 0 ${r} L 0 ${h - r} C 0 ${h - r + k} ${r - k} ${h} ${r} ${h} L ${w - r} ${h} C ${w - r + k} ${h} ${w} ${h - r + k} ${w} ${h - r} L ${w} ${r} C ${w} ${r - k} ${w - r + k} 0 ${w - r} 0 L ${r} 0 C ${r - k} 0 0 ${r - k} 0 ${r} Z`;
}
// A plus with arms t wide and total extent L, round ends, starting at the top end's centre.
function plusPath(L, t) {
  const c = L / 2, a = c - t / 2, b = c + t / 2, q = t / 2, k = q * KAPPA, e = L - q;
  return `M ${c} 0 C ${c + k} 0 ${b} ${q - k} ${b} ${q} L ${b} ${a} L ${e} ${a} C ${e + k} ${a} ${L} ${c - k} ${L} ${c} C ${L} ${c + k} ${e + k} ${b} ${e} ${b} L ${b} ${b} L ${b} ${e} C ${b} ${e + k} ${c + k} ${L} ${c} ${L} C ${c - k} ${L} ${a} ${e + k} ${a} ${e} L ${a} ${b} L ${q} ${b} C ${q - k} ${b} 0 ${c + k} 0 ${c} C 0 ${c - k} ${q - k} ${a} ${q} ${a} L ${a} ${a} L ${a} ${q} C ${a} ${q - k} ${c - k} 0 ${c} 0 Z`;
}

export function mockFigma() {
  const ident = (e, f) => [[1, 0, e], [0, 1, f]];
  const ox = 100, oy = 200;   // the component sits at (100,200) on the page, so relative transforms must be undone
  const vec = (id, x, y, w, h, o) => ({
    id, type: 'VECTOR', name: 'vector', x, y, width: w, height: h, rotation: o.rot || 0, isMask: false, visible: o.visible !== false,
    strokeWeight: o.sw, strokeAlign: 'CENTER', strokeCap: 'ROUND', strokeJoin: o.join, strokeMiterLimit: 4, cornerRadius: o.cr || 0, cornerSmoothing: 0,
    fills: o.fill ? [{ type: 'SOLID', visible: true }] : [], strokes: o.fill ? [] : [{ type: 'SOLID', visible: true }],
    absoluteTransform: o.abs || ident(ox + x, oy + y), absoluteBoundingBox: { x: ox + x, y: oy + y, width: w, height: h },
    absoluteRenderBounds: o.rb ? { x: ox + o.rb[0], y: oy + o.rb[1], width: o.rb[2], height: o.rb[3] } : null,
    vectorPaths: [{ windingRule: 'NONZERO', data: o.d }], dashPattern: [],
  });
  const comp = (id, name, vp, children) => ({ id, type: 'COMPONENT', name, width: 24, height: 24, variantProperties: vp, absoluteTransform: ident(ox, oy), children });
  const OUTER = [4, 6, 16, 12];   // the outer ink box all four drawings below share
  const A = comp('c:1', 'filled=off, stroke=2, radius=0, join=square', { filled: 'off', stroke: '2', radius: '0', join: 'square' }, [
    vec('v:1', 5, 7, 14, 10, { sw: 2, join: 'MITER', rb: OUTER, d: roundedRectPath(14, 10, 0) }),
    vec('v:1b', 0, 0, 3, 3, { sw: 2, join: 'MITER', visible: false, d: roundedRectPath(3, 3, 0) }),   // hidden: must be skipped
    { id: 't:1', type: 'TEXT', name: 'label', characters: 'x', width: 4, height: 4 },                  // text: counted, not measured
  ]);
  const B = comp('c:2', 'filled=on, stroke=2, radius=0, join=square', { filled: 'on', stroke: '2', radius: '0', join: 'square' },
    [vec('v:2', 4, 6, 16, 12, { sw: 2, join: 'MITER', fill: true, rb: OUTER, d: roundedRectPath(16, 12, 0) })]);
  const C = comp('c:3', 'filled=off, stroke=1.5, radius=1, join=round', { filled: 'off', stroke: '1.5', radius: '1', join: 'round' },
    [vec('v:3', 4.75, 6.75, 14.5, 10.5, { sw: 1.5, join: 'ROUND', cr: 1, rb: OUTER, d: roundedRectPath(14.5, 10.5, 1) })]);
  const D = comp('c:4', 'filled=on, stroke=1.5, radius=1, join=round', { filled: 'on', stroke: '1.5', radius: '1', join: 'round' },
    [vec('v:4', 4, 6, 16, 12, { sw: 1.5, join: 'ROUND', fill: true, rb: OUTER, d: roundedRectPath(16, 12, 1.75) })]);
  const set = {
    id: 's:1', type: 'COMPONENT_SET', name: 'box-1, crate', width: 400, height: 64, children: [A, B, C, D],
    variantGroupProperties: { filled: { values: ['off', 'on'] }, stroke: { values: ['2', '1.5', '1'] }, radius: { values: ['0', '1', '2', '3'] }, join: { values: ['square', 'round'] } },
    componentPropertyDefinitions: { filled: { defaultValue: 'off' }, stroke: { defaultValue: '2' }, radius: { defaultValue: '0' }, join: { defaultValue: 'square' } },
  };
  // a turned node: "M 0 0 L 10 0" rotated 90° with its origin at (12,2) must land on x = 12
  const rot = comp('c:5', 'rot', null, [vec('v:5', 12, 2, 10, 0, { sw: 1, join: 'ROUND', abs: [[0, -1, ox + 12], [1, 0, oy + 2]], d: 'M 0 0 L 10 0', rb: null })]);
  const set2 = { id: 's:2', type: 'COMPONENT_SET', name: 'turned', width: 50, height: 50, children: [rot], variantGroupProperties: {}, componentPropertyDefinitions: {} };
  const frame = { id: 'f:1', type: 'FRAME', name: 'Group One', children: [set, set2] };
  const page = { id: '7:118', name: '❖  Icons', type: 'PAGE', children: [frame], loadAsync: async () => {} };
  const root = { name: 'mock', children: [page] };
  return { root, mixed: Symbol('mixed'), fileKey: 'MOCK' };
}

export async function selftest() {
  const { default: assert } = await import('node:assert/strict');
  const results = [];
  const test = async (name, fn) => { try { await fn(); results.push([name, true]); } catch (e) { results.push([name, false, e.stack.split('\n').slice(0, 3).join(' | ')]); } };
  const AsyncFunction = Object.getPrototypeOf(async function () {}).constructor;
  const run = async (opts) => new AsyncFunction('figma', scriptFor('inline', { padTo: 0, ...opts }))(mockFigma());

  await test('inline script is valid JS and the install/verify/run stubs parse', async () => {
    new AsyncFunction('figma', scriptFor('install'));
    new AsyncFunction('figma', scriptFor('verify'));
    new AsyncFunction('figma', scriptFor('run', { source: 'central', names: ['x'] }));
    assert.equal(expectedInstall().ver, EXTRACTOR_VERSION);
  });
  await test('extractor: catalogue lists the set with its axes, aliases split', async () => {
    const r = await run({ source: 'central', mode: 'catalogue' });
    assert.equal(r.rows.length, 2);
    assert.deepEqual(r.rows[0].slice(0, 3), ['Group One', 'box-1', 'crate']);
    assert.equal(r.rows[0][5], 'filled:2|stroke:3|radius:4|join:2');
  });
  const raw = await run({ source: 'central', names: ['box-1'], variants: 'all' });
  await test('extractor: finds the set by name, falls back to an alias, undoes the component offset', async () => {
    assert.equal(raw.concepts.length, 1);
    const d = raw.concepts[0].items[0].drawings;
    assert.equal(d.length, 4);
    assert.deepEqual(d[0].nodes[0].rt, [1, 0, 5, 0, 1, 7]);
    assert.deepEqual(d[0].nodes[0].rb, [4, 6, 16, 12]);
    assert.deepEqual((await run({ source: 'central', names: ['crate'] })).picked, ['Group One|box-1']);
  });
  await test('extractor: variants filter, missing names, chunking and the time budget', async () => {
    assert.equal((await run({ source: 'central', names: ['box-1'], variants: 'default' })).concepts[0].items[0].drawings.length, 1);
    assert.equal((await run({ source: 'central', names: ['box-1'], variants: { filled: ['on'] } })).concepts[0].items[0].drawings.length, 2);
    assert.deepEqual((await run({ source: 'central', names: ['nope'] })).missing, ['nope']);
    const second = await run({ source: 'central', names: ['box-1', 'turned'], from: 1, limit: 1 });
    assert.deepEqual(second.concepts.map((c) => c.name), ['turned']);
    const cut = await run({ source: 'central', names: ['box-1', 'turned'], budgetMs: -1 });
    assert.ok(cut.partial && cut.to === 0 && cut.concepts.length === 0);
  });
  await test('extractor: pads past the host limit so a dump is never echoed into a conversation', async () => {
    const r = await new AsyncFunction('figma', scriptFor('inline', { source: 'central', names: ['box-1'] }))(mockFigma());
    assert.ok(JSON.stringify(r).length >= PAD_TO);
  });
  const norm = normaliseDump(raw);
  const recs = norm.concepts[0].records;
  await test('normalise: paint comes from visible paints, not strokeWeight; hidden and text nodes are skipped but counted', async () => {
    assert.deepEqual(recs.map((r) => r.paths[0].paint), ['stroke', 'fill', 'stroke', 'fill']);
    assert.deepEqual(recs.map((r) => r.strokeWidth), [2, 0, 1.5, 0]);
    assert.deepEqual(recs.map((r) => r.style), ['outline', 'filled', 'outline', 'filled']);
    assert.equal(recs[0].paths.length, 1);
    assert.deepEqual([recs[0].meta.flags.invisibleNodes, recs[0].meta.flags.textNodes], [1, 1]);
  });
  await test('normalise: every measurement is recorded as abs, share of canvas, multiple of stroke', async () => {
    const m = recs[0].measure;
    assert.deepEqual(m.margins.left, { abs: 4, canvas: 0.16667, stroke: 2 });
    assert.deepEqual(m.margins.top, { abs: 6, canvas: 0.25, stroke: 3 });
    assert.deepEqual(m.ink.w, { abs: 16, canvas: 0.66667, stroke: 8 });
    assert.deepEqual(m.stroke, { abs: 2, canvas: 0.08333, stroke: 1 });
    assert.equal(m.inkSource, 'render');
    assert.deepEqual(recs[1].strokeBasis, { value: 2, from: 'variant:stroke' });   // a filled twin borrows the weight its variant names
    assert.deepEqual(recs[1].measure.ink.w, { abs: 16, canvas: 0.66667, stroke: 8 });
  });
  await test('normalise: outline/filled twins share the outer ink box; corner radius = centreline radius + half the stroke, read from the curves', async () => {
    assert.deepEqual(inkOf(recs[2]), inkOf(recs[3]));
    assert.deepEqual(modalRadius(recs[2], 'centreline').r, [1]);
    assert.deepEqual(modalRadius(recs[3], 'edge').r, [1.75]);
    const fr = recs[3].measure.radii.find((q) => near(q.r.abs, 1.75));
    assert.deepEqual([fr.kind, fr.n, fr.r.canvas, fr.r.stroke], ['corner', 4, 0.07292, 1.16667]);
  });
  await test('normalise: a turned node is carried into canvas coordinates', async () => {
    const r = normaliseDump(await run({ source: 'central', names: ['turned'] })).concepts[0].records[0];
    assert.equal(r.paths[0].d, 'M 12 2 L 12 12');
    assert.equal(r.paths[0].local, 'M 0 0 L 10 0');
  });
  await test('geometry: parse, bbox of curves, circular arcs, edge angles', async () => {
    assert.throws(() => parsePath('M 0 0 l 1 1'));
    const circle = (R) => { const k = R * KAPPA; return `M ${R} 0 C ${R + k} 0 ${2 * R} ${R - k} ${2 * R} ${R} C ${2 * R} ${R + k} ${R + k} ${2 * R} ${R} ${2 * R} C ${R - k} ${2 * R} 0 ${R + k} 0 ${R} C 0 ${R - k} ${R - k} 0 ${R} 0 Z`; };
    const bb = bboxOfPath(parsePath(circle(3)));
    assert.ok(near(bb.x0, 0, 1e-9) && near(bb.x1, 6, 1e-9) && near(bb.y1, 6, 1e-9));
    assert.deepEqual(curveCorners(parsePath(circle(3))).map((q) => r4n(q.r)), [3, 3, 3, 3]);
    const e = straightEdges(parsePath('M 0 0 L 6 4 L 0 4 Z')).find((q) => near(Math.abs(q.dx) / Math.abs(q.dy), 1.5));
    assert.ok(e && near(e.angle, 33.69, 0.01));
  });
  await test('arcs: round caps, circles and corners are told apart; line weight read off a bar and a plus', async () => {
    const kinds = (d) => classifyArcs(curveCorners(parsePath(d))).map((q) => `${q.kind}${r4n(q.r)}`).join(' ');
    const stadium = 'M 1 0 L 9 0 C 9.5523 0 10 0.4477 10 1 C 10 1.5523 9.5523 2 9 2 L 1 2 C 0.4477 2 0 1.5523 0 1 C 0 0.4477 0.4477 0 1 0 Z';
    assert.equal(kinds(stadium), 'cap1 cap1');
    assert.equal(kinds(`M 3 0 C ${3 + 3 * KAPPA} 0 6 ${3 - 3 * KAPPA} 6 3 C 6 ${3 + 3 * KAPPA} ${3 + 3 * KAPPA} 6 3 6 C ${3 - 3 * KAPPA} 6 0 ${3 + 3 * KAPPA} 0 3 C 0 ${3 - 3 * KAPPA} ${3 - 3 * KAPPA} 0 3 0 Z`), 'circle3');
    assert.equal(kinds(roundedRectPath(20, 14, 2)), 'corner2 corner2 corner2 corner2');
    assert.equal(kinds(plusPath(16, 2)), 'cap1 cap1 cap1 cap1');   // the cap that wraps round the path's start is still one cap
    assert.equal(r4n(crossThickness(parsePath(plusPath(16, 2)))), 2);
    assert.equal(barThickness(parsePath(stadium)), 2);
  });
  await test('roundings: a run of Bézier pieces between two straight edges is one corner or one cap, smoothed corners report the circle they stand in for', async () => {
    const kinds = (d) => roundings(parsePath(d)).map((q) => `${q.kind}${r4n(q.r)}${q.smooth ? 's' : ''}${q.segs > 1 ? `/${q.segs}` : ''}`).join(' ');
    // a rectangle whose corners are each drawn as n equal pieces of a circle (n = 1: plain rounded), or as one over-long cubic (a smoothed corner)
    const pieces = (cx, cy, R, a0, a1, n) => {
      let d = '';
      for (let i = 0; i < n; i++) {
        const u = a0 + ((a1 - a0) * i) / n, v = a0 + ((a1 - a0) * (i + 1)) / n, k = (4 / 3) * Math.tan((v - u) / 4) * R;
        const P = (t) => [cx + R * Math.cos(t), cy + R * Math.sin(t)], T = (t) => [-Math.sin(t), Math.cos(t)];
        const p0 = P(u), p3 = P(v), t0 = T(u), t3 = T(v);
        d += ` C ${p0[0] + k * t0[0]} ${p0[1] + k * t0[1]} ${p3[0] - k * t3[0]} ${p3[1] - k * t3[1]} ${p3[0]} ${p3[1]}`;
      }
      return d;
    };
    const rect = (w, h, R, n) => { const q = Math.PI / 2; return `M 0 ${h - R} L 0 ${R}${pieces(R, R, R, 2 * q, 3 * q, n)} L ${w - R} 0${pieces(w - R, R, R, 3 * q, 4 * q, n)} L ${w} ${h - R}${pieces(w - R, h - R, R, 0, q, n)} L ${R} ${h}${pieces(R, h - R, R, q, 2 * q, n)} Z`; };
    assert.equal(kinds(rect(20, 14, 3, 1)), 'corner3 corner3 corner3 corner3');
    assert.equal(kinds(rect(20, 14, 3, 3)), 'corner3/3 corner3/3 corner3/3 corner3/3');
    const squircle = 'M 0 11 L 0 3 C 0 1.2 1.2 0 3 0 L 17 0 C 18.8 0 20 1.2 20 3 L 20 11 C 20 12.8 18.8 14 17 14 L 3 14 C 1.2 14 0 12.8 0 11 Z';
    assert.equal(kinds(squircle), 'corner3s corner3s corner3s corner3s');   // handles 1.8 where a circle has 1.657: not the circle, but it stands in for the 3
    assert.equal(kinds(plusPath(16, 2)), 'cap1/2 cap1/2 cap1/2 cap1/2');
    assert.equal(kinds('M 1 0 L 9 0 C 9.5523 0 10 0.4477 10 1 C 10 1.5523 9.5523 2 9 2 L 1 2 C 0.4477 2 0 1.5523 0 1 C 0 0.4477 0.4477 0 1 0 Z'), 'cap1/2 cap1/2');
    assert.equal(kinds('M 5 0 L 0 0 C 0 3 3 6 6 6'), 'arc6');   // an open path that ends in a curve has no straight edge after it: a free arc, not a corner
  });
  await test('envelope: the host-saved bridge wrapper is unwrapped; errors are loud', async () => {
    const wrapped = JSON.stringify({ _mcp: 'x', success: true, result: raw });
    assert.equal(readEnvelope(wrapped).kind, RAW_SCHEMA);
    assert.throws(() => readEnvelope(JSON.stringify({ _mcp: 'x', success: true, result: { error: 'boom' } })), /boom/);
  });

  const failed = results.filter((r) => !r[1]);
  for (const [name, ok, msg] of results) console.log(`${ok ? 'ok  ' : 'FAIL'} ${name}${ok ? '' : '\n       ' + msg}`);
  console.log(`\n${results.length - failed.length}/${results.length} passed`);
  return failed.length === 0;
}

// ───────────────────────────────────────────────────────────────────────────
// PART J — command line.   node tools/audit/refs/figma.mjs help
// ───────────────────────────────────────────────────────────────────────────
const BOOLEAN_FLAGS = new Set(['dry-run', 'sample-set', 'catalogue', 'no-calibrate', 'inline', 'json', 'help']);
function parseArgs(argv) {
  const pos = [], flags = {};
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a.startsWith('--')) {
      const k = a.slice(2), nxt = argv[i + 1];
      if (!BOOLEAN_FLAGS.has(k) && nxt !== undefined && !nxt.startsWith('--')) { flags[k] = nxt; i++; } else flags[k] = true;
    } else pos.push(a);
  }
  return { pos, flags };
}

// "stroke=2|1;join=round" → { stroke: ['2','1'], join: ['round'] }
export function parseVariantSpec(s) {
  if (!s || s === 'all' || s === 'default') return s || 'all';
  const o = {};
  for (const part of String(s).split(';')) {
    const m = part.match(/^\s*([^=]+)=(.*)$/);
    if (!m) throw new Error(`bad --variants "${s}" (want all | default | axis=v1|v2;axis2=v)`);
    o[m[1].trim()] = m[2].split('|').map((v) => v.trim());
  }
  return o;
}

export function optionsFromFlags(source, flags) {
  if (!SOURCES[source]) throw new Error(`unknown source "${source}" (${Object.keys(SOURCES).join(' | ')})`);
  const o = { source, mode: flags.catalogue ? 'catalogue' : 'extract' };
  if (flags.names) o.names = String(flags.names).split(',').map((s) => s.trim()).filter(Boolean);
  else if (flags['sample-set']) o.names = SAMPLE[source];
  if (flags.match) o.match = String(flags.match);
  if (flags.group) o.group = String(flags.group);
  if (flags.n) o.sample = Number(flags.n);
  if (flags.variants) o.variants = parseVariantSpec(flags.variants);
  if (flags.from) o.from = Number(flags.from);
  if (flags.limit) o.limit = Number(flags.limit);
  if (flags['max-variants']) o.maxVariants = Number(flags['max-variants']);
  if (!flags['no-calibrate'] && SOURCES[source].calibrate.length && o.mode === 'extract') o.calibrate = SOURCES[source].calibrate.map((c) => c.name);
  return o;
}

function printSummary(s) {
  const kv = (o) => Object.entries(o || {}).map(([k, v]) => `${k} ×${v}`).join(' · ') || '—';
  console.log(`\n== ${s.label} (${s.source}) — ${s.concepts} concepts, ${s.drawings} drawings in the sample`);
  if (!s.drawings) return;
  console.log(`  canvas          ${kv(s.canvases)}`);
  console.log(`  masters         ${kv(s.masters)}   |   masters per concept: ${kv(s.mastersPerConcept)}`);
  console.log(`  styles          ${kv(s.styles)}`);
  console.log(`  painted stroke  ${s.paintedStroke.drawings} drawings; weights ${kv(s.paintedStroke.byWeight)}; caps ${kv(s.paintedStroke.cap)}; joins ${kv(s.paintedStroke.join)}`);
  console.log(`  stroke basis    ${kv(s.strokeBasis)}`);
  for (const [k, v] of Object.entries(s.strokeShare)) console.log(`  line weight     master ${k}: ${v.stroke.join(' / ')} units = ${v.canvas.map((x) => (x * 100).toFixed(2) + '%').join(' / ')} of canvas`);
  const t = s.twins;
  console.log(`  filled twin     ${t.conceptsWithBoth}/${t.ofConcepts} concepts have both; ${t.sameOuterBox}/${t.pairs} pairs share the outline's outer box (±0.01), ${t.within025}/${t.pairs} within 0.25; max difference ${t.maxDelta}`);
  if (t.conceptsThatDiffer.length) console.log(`                  ${t.conceptsThatDiffer.length} concept(s) have a pair that differs: ` + t.conceptsThatDiffer.slice(0, 8).map((e) => `${e.name} ${e.differ}/${e.pairs} (max ${e.maxDelta})`).join(' · '));
  if (s.calibration) {
    console.log('  implied line weight by size (read off the drawings; no stroke property exists):');
    for (const [m, e] of Object.entries(s.calibration)) console.log(`                  ${String(m).padStart(2)}: ${e.value} via ${e.glyph}${e.check.length ? ' (agrees: ' + e.check.map((c) => c.glyph + ' ' + c.value).join(', ') + ')' : ''}${e.filled ? ` · filled theme ${e.filled.value} via ${e.filled.glyph}` : ''}`);
  }
  const r = s.masterRescale;
  if (r.pairs) console.log(`  masters redrawn? ${r.pairs} adjacent-size pairs: ${r.differentStructure} different structure, ${r.redrawn} same structure but moved >0.5, ${r.near} moved ≤0.5, ${r.rescale} pure rescale (≤0.05)`);
  for (const [m, l] of Object.entries(s.modalCornerRadius)) console.log(`  corner radius   master ${m}: ` + l.map((e) => `r${e.r} (${e.xStroke == null ? '—' : e.xStroke + '× its ' + e.strokeUnits + ' stroke'}, ${(e.canvasShare * 100).toFixed(1)}% of canvas, n=${e.n}${e.smooth ? `, ${e.smooth} smoothed` : ''})`).join(' · '));
}

const HELP = `figma.mjs — Figma reference harness (plan card 0.3)

  sources                                list the four sources, their Figma page ids and calibration glyphs
  script install                         JS to paste into figma_execute once per bridge session
  script verify                          JS that returns {ver, chars, hash} of the installed extractor; prints the expected value on stderr
  script run <source> [options]          JS stub with the options baked in; paste into figma_execute (timeout 30000)
       --names a,b,c | --sample-set      which concepts (exact name or alias); --sample-set = the built-in ~26
       --match REGEX  --group TEXT       more concepts / restrict to a category
       --n N                             no names: N concepts spread evenly across the source
       --variants all|default|"axis=v|v;axis=v"   which variants of a set to read (default all)
       --from I --limit K                chunk a long list (a partial dump says where to continue)
       --max-variants N                  cap on variants read per set (default 80; Fluent's Border has 66)
       --catalogue                       just list every concept (name, variants, axes, canvas)
       --no-calibrate  --inline          skip calibration glyphs / embed the whole extractor instead of the stub
  ingest <file…> [--dry-run]             normalise a dump (the host-saved tool-result file works as is) and write it under
                                         research/references/<source>/figma/
  reingest <source|all> [--dry-run]      rebuild the normalised files from the raw dumps already on disk (no Figma needed)
  plan <source> [--chunk K] [--total N]  the chain of 'script run … --from i --limit K' commands that covers a whole source
                                         (total from the ingested catalogue unless --total is given)
  summary [source|all] [--json]          canvas, stroke, filled-twin and master facts from what has been ingested
  probe folder-1                         re-measure the hand-measured Central folder-1 claims: stated vs measured
  selftest                               mock-Figma test of the extractor, normaliser and geometry`;

async function main() {
  const { pos, flags } = parseArgs(process.argv.slice(2));
  const cmd = pos[0];
  if (!cmd || cmd === 'help' || flags.help) { console.log(HELP); return 0; }
  if (cmd === 'sources') {
    for (const [k, v] of Object.entries(SOURCES)) console.log(`${k.padEnd(9)} page ${v.pageId.padEnd(12)} "${v.pageName}"  calibrate: ${v.calibrate.map((c) => c.name + '(' + c.how + ')').join(', ') || '—'}  sample: ${SAMPLE[k].length} concepts`);
    return 0;
  }
  if (cmd === 'script') {
    if (pos[1] === 'install') { process.stdout.write(scriptFor('install') + '\n'); return 0; }
    if (pos[1] === 'verify') { process.stdout.write(scriptFor('verify') + '\n'); console.error('expected: ' + JSON.stringify(expectedInstall())); return 0; }
    if (pos[1] === 'run') {
      const o = optionsFromFlags(pos[2], flags);
      process.stdout.write(scriptFor(flags.inline ? 'inline' : 'run', o) + '\n');
      return 0;
    }
    throw new Error('script install | script verify | script run <source> [options]');
  }
  if (cmd === 'ingest') {
    const files = pos.slice(1);
    if (!files.length) throw new Error('ingest <file…>');
    for (const f of files) {
      const raw = readEnvelope(fs.readFileSync(f, 'utf8'));
      const rep = ingestRaw(raw, { dryRun: !!flags['dry-run'] });
      console.log(`${flags['dry-run'] ? '[dry run] ' : ''}${rep.source} ${rep.mode}: ${rep.concepts} concepts${rep.drawings != null ? `, ${rep.drawings} drawings` : ''} → ${path.relative(REPO, rep.dir)}/ (${rep.files.length} files)`);
      for (const w of rep.warnings) console.log('  warning: ' + w);
    }
    return 0;
  }
  if (cmd === 'reingest') {
    const which = !pos[1] || pos[1] === 'all' ? Object.keys(SOURCES) : [pos[1]];
    for (const src of which) for (const rep of reingest(src, { dryRun: !!flags['dry-run'] })) console.log(`${flags['dry-run'] ? '[dry run] ' : ''}${rep.source}: ${rep.concepts} concepts, ${rep.drawings} drawings from a raw dump`);
    return 0;
  }
  if (cmd === 'plan') {
    const source = pos[1];
    if (!SOURCES[source]) throw new Error('plan <source> [--chunk K] [--total N]');
    const cat = readJson(path.join(sourceDir(source), 'catalogue.json'));
    const total = Number(flags.total) || (cat && cat.enumerated);
    if (!total) throw new Error('no catalogue ingested for ' + source + ' — run `script run ' + source + ' --catalogue`, ingest it, or pass --total N');
    const chunk = Number(flags.chunk) || 100;
    const extra = flags.variants ? ` --variants "${flags.variants}"` : '';
    for (let i = 0; i < total; i += chunk) console.log(`node tools/audit/refs/figma.mjs script run ${source} --match . --from ${i} --limit ${chunk}${extra}`);
    console.log(`# ${Math.ceil(total / chunk)} chunks of ${chunk} for ${total} concepts; paste each into figma_execute (timeout 30000), then \`ingest\` the saved file. Keep calls sequential.`);
    return 0;
  }
  if (cmd === 'summary') {
    const which = !pos[1] || pos[1] === 'all' ? Object.keys(SOURCES) : [pos[1]];
    const all = which.map(summarise);
    if (flags.json) console.log(JSON.stringify(all, null, 1)); else all.forEach(printSummary);
    return 0;
  }
  if (cmd === 'probe') {
    if (pos[1] !== 'folder-1') throw new Error('probe folder-1');
    console.log(formatRows(probeFolder1()));
    return 0;
  }
  if (cmd === 'selftest') return (await selftest()) ? 0 : 1;
  throw new Error(`unknown command "${cmd}" — try: help`);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main().then((code) => process.exit(code), (e) => { console.error('error: ' + e.message); process.exit(1); });
}
